const RankBadge = ({ rank, size = 'w-9 h-9', className = '' }) => {
  const key = rank?.name === 'Master' ? 'Heroic I' : `${rank?.name || 'Bronze'} ${rank?.level || 'III'}`;
  const src = RANK_BADGES[key] || RANK_BADGES['Bronze III'];
  return <img src={src} alt={`${rank?.name || 'Bronze'} ${rank?.level || 'III'}`} className={`${size} object-contain ${className}`} />;
};

