  // Daily automation safety-net. The primary next-day clone is created when the
  // admin marks a match started; this listener also repairs missed days after a
  // refresh or when the browser was closed. New matches never copy joinEntries.
  useEffect(() => {
    if (!automatedTemplates.length) return;
    const generateDueMatches = async () => {
      const now = new Date();
      const dateKey = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
      for (const tpl of automatedTemplates) {
        if (tpl.lastGeneratedDate && tpl.lastGeneratedDate >= dateKey) continue;
        const matchId = `m_auto_${tpl.id}_${dateKey}`;
        const newMatch = { id: matchId, templateId: tpl.id, generatedDate: dateKey, category: tpl.category, categoryId: tpl.categoryId, title: tpl.title, time: `${dateKey} ${tpl.timeLabel}`, prizePool: tpl.prizePool, perKill: tpl.perKill, entryFee: tpl.entryFee, map: tpl.map || 'BERMUDA', mode: tpl.mode, status: 'upcoming', started: false, slotsFilled: 0, totalSlots: tpl.totalSlots, image: tpl.image, rules: tpl.rules, roomInfo: { id: '', pass: '' }, prizeTable: tpl.prizeTable || [] };
        try {
          const ref = doc(db, 'tournaments', matchId);
          await runTransaction(db, async (transaction) => {
            const snap = await transaction.get(ref);
            if (!snap.exists()) transaction.set(ref, newMatch);
          });
          await setDoc(doc(db, 'automatedTemplates', tpl.id), { ...tpl, lastGeneratedDate: dateKey }, { merge: true });
          setTournaments(prev => prev.some(m => m.id === matchId) ? prev : [...prev, newMatch]);
        } catch (e) { console.error('Daily match clone error:', e); }
      }
    };
    generateDueMatches();
    const interval = setInterval(generateDueMatches, 60 * 1000);
    return () => clearInterval(interval);
  }, [automatedTemplates]);

